/*
    SKY PAINTER

    Paint onto a skydome texture and see the render update interactively


    Usage:

     - Hold Q to switch to full-screen paint view. Hold A for picture-in-picture paint view.

     - Draw in the big circle to paint with the brush. Bright marks correspond to bright patches
       of incident illumination on the skylight.

     - Release Q to rebuild the skylight and restart the render.

     - In render view, click and drag with the mouse to orbit the camera

     - Hold W to dolly and truck the camera  

     - Hold E to change the focal plane

     - Check out Common.hlsl for more adjustable parameters.


    UI Configurator:

       Colour picker (top):

        - Select the hue using the outer ring. Adjust the saturation and lightness using the inner triangle.
          NOTE: A colour grade is applied bya default. Turn this off using the toggle second from the left.

       Parameter dials (middle row, left to right):

        - Ring icon:        Adjust brush size
        - Solid disc icon:  Adjust brush hardness
        - Sun icon:         Adjust brush brightness
        - 'A' icon:         Adjust brush alpha (opacity)

       Toggles (bottom row, left to right):

        - Wave icon:        Enable to auto-scale the skylight so it has a constant power regardless of the painted values.
        - 3-circle icon:    Enable post-process colour grading
        - Star icon:        Enable post-process lens bloom
        - Rainbow icon:     Enable post-process chromatic blur
        - Spotlight icon:   Enable spotlight effect 


       Hit the X button to reset the skylight.  
*/


vec3 Vignette(in vec3 rgb, in vec2 fragCoord)
{
    #define kVignetteStrength         1.             // The strength of the vignette effect
    #define kVignetteScale            0.6            // The scale of the vignette effect
    #define kVignetteExponent         2.5            // The rate of attenuation of the vignette effect

    vec2 uv = fragCoord / iResolution.xy;
    uv.x = (uv.x - 0.5) * (iResolution.x / iResolution.y) + 0.5;     

    float x = 2.0 * (uv.x - 0.5);
    float y = 2.0 * (uv.y - 0.5);

    float dist = sqrt(x*x + y*y) / kRoot2;

    float v = mix(1.0, max(0.0, 1.0 - pow(dist * kVignetteScale, kVignetteExponent)), kVignetteStrength);
    return rgb * v;
    //return pow(rgb, vec3(1. + (1. - v)));
}

vec3 ZoomBlur( in vec2 xyScreen )
{
    #define kMaxBlurSteps 50
    #define kMaxBlurMag 0.04
    #define kTime (iTime * 0.2)
    #define kOrbitRadius 0.0

    float theta = -0.25 * kTwoPi * (iTime - 0.01);

    vec2 blurCentroid = (vec2(0.5) + vec2(cos(kTime), sin(kTime)) * kOrbitRadius) * vec2(1., iResolution.y/iResolution.x);

    float d = length(xyScreen - iResolution.xy * 0.5) / iResolution.x;
    d = 1. - exp(-sqr(d * 3.));
    float gain = 1.;
    int kBlurSteps = int(float(kMaxBlurSteps) * d);
    float kBlurMag = kMaxBlurMag * d;

    if(kBlurSteps <= 1)
    {
        vec4 texel = texelFetch(iChannel0, ivec2(xyScreen), 0);
        return gain * texel.xyz / max(1., texel.w);
    }    

    vec2 uvScreen = vec2(1., iResolution.y/iResolution.x) * xyScreen / iResolution.xy;     
    vec2 originRelative = (uvScreen - blurCentroid);

    float sumWeights = 0.;
    vec3 sigma = vec3(0.);
    for(int idx = 0; idx < kBlurSteps; ++idx)
    {
        float xi = OrderedDither(ivec2(xyScreen));
        float t = (xi + float(idx)) / float(kBlurSteps);        
        vec2 uvSample = uvScreen + originRelative * kBlurMag * -pow(t, 2.);

        // Exclude pixels belonging to the UI state
        if(int(uvSample.x * iResolution.x) < kUIState && int(uvSample.y * iResolution.y) == 0) { continue; }

        vec4 texel = texture(iChannel0, uvSample / vec2(1., iResolution.y/iResolution.x), 0.);
        vec3 spectrum = mix(kOne, 2. * Hue(1. - float(idx) / float(kBlurSteps - 1)), d);
        sigma += spectrum * gain * (texel.xyz / max(1., texel.w));
        sumWeights += 1.;
    }

    return sigma / float(sumWeights);
}

float Smoothstep(float a, float b, float t) { return mix(a, b, t * t * (3. - 2. * t)); }

vec3 ChromaticAberration(sampler2D sampler, in vec2 xyScreen, int chnl, float magnitude)
{
    #define kAbbSafeZone 0.
    #define kAbbMagnitude 0.02

    vec3 rgb = kZero;
    vec2 ratio = vec2(max(1., iResolution.x / iResolution.y), max(1., iResolution.y / iResolution.x));
    vec2 uv = ratio * (xyScreen / iResolution.xy - vec2(0.5));
    float d = length(uv);

    for(int c = 0; c < 3; ++c)
    {
        vec2 uvc = uv / (1. + Smoothstep(0., kAbbMagnitude, saturate(d - kAbbSafeZone) * mix(0.5, 0., (float(c) + OrderedDither(ivec2(xyScreen))) / 3.)));
        vec4 texel = texture(sampler, (uvc / ratio) + vec2(0.5), 0.);
        rgb[c] = texel[c] / texel.w;

    }
    return rgb;
}

// Maps screen coords to [-1, 1], plus pixel differential
vec3 TransformScreenToWorldDiffs(vec2 p, vec2 iResolution)
{    
    return vec3(ScreenToNormalisedScreen(p, iResolution), kRoot2 / iResolution.y);
}


vec3 Metro(vec3 p)
{
    p = saturate(p);
    const float[30] c = float[30](
        -0.0180678482422229, 1.52889467695658, -0.0623136057660897, -0.155732388555471, -0.250867496990887, 0.0391384108545744, -0.00128400941904526, 
        -0.100944170159481, 0.0831639058413459, -0.0383214788806629, -0.185943804438669, 0.0970718501789022, 1.70442171194878, 0.394965137180801, 
        -0.0978565424331064, -0.827273202026112, -0.146243936353348, 0.130000627814526, 0.0780044400302885, -0.195279506849575, -0.189357731622912, 
        0.164477432439256, 0.475827161052928,1.79067080168516, -0.00482185897201533, -0.361898368087104,-0.688844153606519, -0.0102402980123174, 
        -0.0591881220813021,-0.11818940425772);

    vec3 f;
    for(int i = 0, j = 0; i < 3; ++i, j += 10)
    {
        f[i] = c[j] +
               p.x * (c[j+1] + p.x * c[j+4] + p.y * c[j+7] + p.z * c[j+9]) +
               p.y * (c[j+2] + p.y * c[j+5] + c[j+8]*p.z) +
               p.z * (c[j+3] + p.z * c[j+6]);
    }

    return saturate(f);
}

// Neural colour grading. Shout out to UnitZeroOne for sharing this code! :-) 
vec3 applyColorGrade(vec3 inputColor) 
{
    inputColor = saturate(inputColor.zyx);

 // Named constants up front
    const float ZERO  = 0.0;
    const float PAD   = 0.0;  // used for padding only
    const float HALF  = 0.5;
    const float ONE   = 1.0;
    const float TWO   = 2.0;
    const float GELU_C1 = 0.7978845608;
    const float GELU_C2 = 0.044715;

   const mat4 layer0_chunk0_W0 = mat4(0.237038, 0.002839, -0.613395, 0.023955, 2.190638, 0.681709, -2.263870, -0.567830, 0.501725, 1.600221, -0.383257, 0.890942, PAD, PAD, PAD, PAD);
   const vec4 layer0_chunk0_bias = vec4(-0.287044, 0.280783, 0.290978, 0.598706);

   const mat4 layer0_chunk1_W0 = mat4(-0.137439, -0.103585, -0.010283, -1.756933, -0.938134, 1.964871, -0.696499, 1.249109, 1.416610, -0.654387, -0.856150, 1.315522, PAD, PAD, PAD, PAD);
   const vec4 layer0_chunk1_bias = vec4(-0.027628, 0.506725, 0.573981, 0.743510);

   const mat4 layer2_chunk0_W0 = mat4(3.334981, 0.692745, -2.249792, -1.533133, 0.759040, -0.884428, 0.228476, 1.654801, -1.449445, 0.674627, 1.597890, 0.084069, 1.227800, 0.103707, 2.272768, -3.488576);
   const mat4 layer2_chunk0_W1 = mat4(-3.658784, 0.920236, 2.443871, 1.958547, 1.074470, -0.660618, 1.283018, 0.921886, 1.856311, -0.596886, -2.903828, 1.161765, 0.368526, -0.286363, -0.506707, -0.171955);
   const vec4 layer2_chunk0_bias = vec4(1.218964, 0.054669, 0.264244, 0.295188);

   const mat4 layer2_chunk1_W0 = mat4(-0.191983, -0.747375, 0.912338, -1.968686, 0.272265, -0.705990, 0.595160, 1.205564, -0.024412, -0.238474, -0.449195, 0.163486, -1.953892, 1.715119, -0.194429, -2.550383);
   const mat4 layer2_chunk1_W1 = mat4(1.502533, -2.311996, -1.078473, 1.977682, -0.300410, 1.483174, 0.281399, 1.433337, -2.760890, -0.152508, -0.236289, 0.070996, 0.006024, -0.143973, 0.195464, -0.261372);
   const vec4 layer2_chunk1_bias = vec4(1.241102, 0.342907, 0.901451, 0.191256);

   const mat4 layer4_chunk0_W0 = mat4(0.208272, -0.118866, 0.661599, PAD, -1.598513, -2.092330, -0.095411, PAD, 0.630788, -0.224832, 0.052688, PAD, -3.094599, -0.439651, -0.093030, PAD);
   const mat4 layer4_chunk0_W1 = mat4(3.054257, 0.375831, -0.121975, PAD, 0.069616, 0.252565, 0.532385, PAD, -0.114408, 0.896074, -0.793594, PAD, 3.216065, 0.745465, -0.031920, PAD);
   const vec4 layer4_chunk0_bias = vec4(0.230162, -0.046474, -1.497791, PAD);

    // Scale inputColor from [0,1] to [-1,1]
    vec3 scaledColor = inputColor * TWO - ONE;

    vec4 layer0_chunk0_out = layer0_chunk0_W0 * vec4(scaledColor, ZERO) + layer0_chunk0_bias;

    vec4 layer0_chunk1_out = layer0_chunk1_W0 * vec4(scaledColor, ZERO) + layer0_chunk1_bias;

    layer0_chunk0_out = layer0_chunk0_out * (ONE + tanh(GELU_C1 * (layer0_chunk0_out + GELU_C2 * layer0_chunk0_out*layer0_chunk0_out*layer0_chunk0_out))) * HALF;
    layer0_chunk1_out = layer0_chunk1_out * (ONE + tanh(GELU_C1 * (layer0_chunk1_out + GELU_C2 * layer0_chunk1_out*layer0_chunk1_out*layer0_chunk1_out))) * HALF;

    vec4 layer2_chunk0_out = layer2_chunk0_W0 * layer0_chunk0_out + layer2_chunk0_W1 * layer0_chunk1_out + layer2_chunk0_bias;

    vec4 layer2_chunk1_out = layer2_chunk1_W0 * layer0_chunk0_out + layer2_chunk1_W1 * layer0_chunk1_out + layer2_chunk1_bias;

    layer2_chunk0_out = layer2_chunk0_out * (ONE + tanh(GELU_C1 * (layer2_chunk0_out + GELU_C2 * layer2_chunk0_out*layer2_chunk0_out*layer2_chunk0_out))) * HALF;
    layer2_chunk1_out = layer2_chunk1_out * (ONE + tanh(GELU_C1 * (layer2_chunk1_out + GELU_C2 * layer2_chunk1_out*layer2_chunk1_out*layer2_chunk1_out))) * HALF;

    vec4 layer4_chunk0_out = layer4_chunk0_W0 * layer2_chunk0_out + layer4_chunk0_W1 * layer2_chunk1_out + layer4_chunk0_bias;

    layer4_chunk0_out = ONE / (ONE + exp(-layer4_chunk0_out));

    return saturate(layer4_chunk0_out.xyz);
}

float SDFCircleSolid(vec2 p, vec2 o, float r, float dXYdP)
{
    return saturate((r - length(o - p)) / dXYdP);
}

float SDFCircleOutline(vec2 p, vec2 o, float r, float thickness, float dXYdP)
{
    return saturate((thickness - abs(length(o - p) - r)) / dXYdP);
}

float SDFCircleArcOutline(vec2 p, vec2 o, float r, vec2 range, float thickness, float dXYdP)
{
    float phi = atan(p.y - o.y, p.x - o.x) + kPi;    
    if((range.x < range.y && (phi < range.x || phi > range.y)) || 
       (range.x > range.y && (phi > range.x || phi < range.y)))
    {
        phi = (min(abs(range.x - phi), abs(range.x - kTwoPi * sign(range.x - kPi) - phi)) < 
               min(abs(range.y - phi), abs(range.y - kTwoPi * sign(range.y - kPi) - phi))) ? range.x : range.y;                   
    }

    vec2 pPerp = r * vec2(-cos(phi), sin(-phi));     
    return saturate((thickness - length(p - pPerp)) / dXYdP);
}

float LoadingIcon(ivec2 xyScreen, ivec2 resolution)
{    
    #define kLoadingScale             2.
    #define kLoadingInnerRadius       (0.05 * kLoadingScale)
    #define kLoadingOuterRadius       (0.07 * kLoadingScale)
    #define kLoadingThickness         (0.5 * (kLoadingOuterRadius - kLoadingInnerRadius))
    #define kLoadingCycle             ((4 + kPDF2PhiSteps + kPDF2ThetaSteps) / 2)

    vec3 uvView = TransformScreenToWorldDiffs(vec2(xyScreen), vec2(resolution));   

    // Exclude anything outside the outer radius
    if(length2(uvView) < sqr(kLoadingOuterRadius * 1.1))
    {    
        // Define an arc that cyclically folds and unfolds
        float phiStart = kTwoPi * mix(mod(float(iFrame) * (1.0 / float(kLoadingCycle)), 1.0), 0.0, float((iFrame / kLoadingCycle) & 1));
        float phiEnd = kTwoPi * mix(1.0, mod(float(iFrame) * (1.0 / float(kLoadingCycle)), 1.0), float((iFrame / kLoadingCycle) & 1));

        return (SDFCircleOutline(uvView.xy, vec2(0.), kLoadingOuterRadius, uvView.z * 2., uvView.z) +
                SDFCircleArcOutline(uvView.xy, vec2(0.), kLoadingInnerRadius, vec2(phiStart, phiEnd), kLoadingThickness, uvView.z)); 
    }
    return 0.;
}

void OverlayConfig(vec2 xyScreen, vec4 state, inout vec3 L)
{
    // If the drawing panel is displayed, fade it in or out based on the transition value
    float configAlpha = max(state.x, state.y);
    if(configAlpha > 0.)
    {
        // Fade in the config with a very soft touchdown. Fade out more abruptly.
        configAlpha = (state.z > 0.) ? pow(configAlpha, 0.2) : smoothstep(0.,1., configAlpha);    
        float scale;
        vec2 uv;

        if(state.x > 0.)
        {
            uv = ((xyScreen / iResolution.xy - 0.5) / mix(1.1, 1., configAlpha)) + 0.5;        
        }
        else
        {
            uv = ((xyScreen / iResolution.xy - vec2(mix(-0.2, 0.5 * kPiPSize, configAlpha), 0.5 * kPiPSize)) / kPiPSize) + 0.5;   
        }

        if(uv.x >= 0. && uv.x <= 1. && uv.y >= 0. && uv.y <= 1.)
        {
            vec4 LConf = texture(iChannel3, clamp(uv, vec2(0., 2. / iResolution.y), vec2(1.)), 0.);

            if(length2(uv * vec2(iResolution.x / iResolution.y, 1.) - vec2(0.5)) < 0.25)
            {
                LConf.xyz = sqrt(0.1 * LConf.xyz);
                LConf.xyz = pow(LConf.xyz * 0.5, vec3(.7));
            }           

            L = Blend(vec4((L), 1.), vec4(saturate(LConf.xyz), LConf.w * configAlpha)).xyz;
        }        
    }
}

void mainImage( out vec4 rgba, in vec2 xyScreen )
{                  
    rgba = vec4(0.);
    vec4 pdfState = texelFetch(iChannel1, kPDF2State, 0);

    // If the PDF is rebuilding, display the loading icon for a few frames
    vec3 L = kZero;
    if(!(int(pdfState.x) < 4 + kPDF2PhiSteps + kPDF2ThetaSteps && !PeekConfig(iFrame) && !IsADown(uint(pdfState.y))))
    {   
        if(IsToggleSet(kIDAberration, iChannel3))
        {
            //L = ChromaticAberration(iChannel0, xyScreen, 1, 0.007);    
            L = ZoomBlur(xyScreen);
        }
        else
        {
            vec4 texel = texelFetch(iChannel0, ivec2(xyScreen.x, max(1, int(xyScreen.y))), 0);
            L = texel.xyz / max(1., texel.w);
        }

        float bloomGain = GetTogglePos(kIDBloom, iChannel3);
        if(bloomGain > 0.)
        {
            vec3 bloom = SeparableBlurUp(ivec2(xyScreen), ivec2(iResolution), vec2(0.05), vec3(1.5, 1.8, 2.4), 0, iChannel2) * 1.; 
            bloom += SeparableBlurUp(ivec2(xyScreen), ivec2(iResolution), vec2(0.1), vec3(1.0, 1.8, 2.4), 1, iChannel2) * 1.;
            L += pow(max(kZero, bloom - kOne * 0.1), 1.7 * vec3(1., 1.1, 1.2)) * 0.5 * bloomGain; 
        }

        // Gaina and gamma correction
        L = pow(L * 0.6, vec3(1. / 2.));

        // Apply optical vignetting
        L = Vignette(L, xyScreen);  
    }   


    OverlayConfig(xyScreen, texelFetch(iChannel3, ivec2(3, 0), 0), L);

    /*if(PeekConfig(iFrame))
    {
        L = mix(L, vec3(1., 0., 0.), LoadingIcon(ivec2(xyScreen), ivec2(iResolution.xy)));
    }*/

    float gradeLevel = GetTogglePos(kIDGrade, iChannel3);
    if(gradeLevel > 0.)
    {
        L = mix(L, applyColorGrade(L), gradeLevel);
    }

    rgba = vec4(L, 1.);


    //if(abs(int(xyScreen.x) - int(iResolution.x * 0.5)) <= 1) { rgba.xyz =kZero; }
}

