struct Transform
{
    vec3 trans;
    mat3 rot;
    float sca;
};

RayBasic RayToObjectSpace(in RayBasic world, in Transform transform) 
{
    RayBasic object;
    object.o = world.o - transform.trans;
    object.d = world.d + object.o;
    object.o = transform.rot * object.o / transform.sca;
    object.d = (transform.rot * object.d / transform.sca) - object.o;
    return object;
}

mat3 Identity()
{
    return mat3(vec3(1.0, 0.0, 0.0), vec3(0.0, 1.0, 0.0), vec3(0.0, 0.0, 1.0));
}

mat3 ScaleMat3(float scale)
{
    float invScale = 1.0f / scale;
    return mat3(vec3(invScale, 0.0, 0.0),
            vec3(0.0, invScale, 0.0),
            vec3(0.0, 0.0, invScale));
}

mat3 RotXMat3(float theta)
{
    float cosTheta = cos(theta), sinTheta = sin(theta);
    return mat3(vec3(1.0, 0.0, 0.0),
            vec3(0.0, cosTheta, -sinTheta),
            vec3(0.0, sinTheta, cosTheta));
}

mat3 RotYMat3(const float theta)
{
    float cosTheta = cos(theta), sinTheta = sin(theta);
    return mat3(vec3(cosTheta, 0.0, sinTheta),
            vec3(0.0, 1.0, 0.0),
            vec3(-sinTheta, 0.0, cosTheta));
}

mat3 RotZMat3(const float theta)
{
    float cosTheta = cos(theta), sinTheta = sin(theta);
    return mat3(vec3(cosTheta, -sinTheta, 0.0),
            vec3(sinTheta, cosTheta, 0.0),
            vec3(0.0, 0.0, 1.0));
}

mat2 RotMat2(float theta)
{
    float cosTheta = cos(theta), sinTheta = sin(theta);
    return mat2(sinTheta, cosTheta, -cosTheta, sinTheta);
}

Transform CompoundTransform(vec3 trans, vec3 rot, float scale)
{
    Transform t;
    t.rot = Identity();
    t.sca = scale;
    t.trans = trans;

    if (rot.x != 0.0) { t.rot *= RotXMat3(rot.x); }
    if (rot.y != 0.0) { t.rot *= RotYMat3(rot.y); }
    if (rot.z != 0.0) { t.rot *= RotZMat3(rot.z); }

    //if (scale != 1.0f) { t.rot *= ScaleMat3(scale); }

    return t;
}

Transform IdentityTransform()
{
    Transform t;
    t.rot = Identity();
    t.sca = 1.0;
    t.trans = kZero;
    return t;
}

vec2 ScreenToNormalisedScreen(vec2 p, vec2 iRes)
{   
    return (p - vec2(iRes) * 0.5) / float(iRes.y); 
}

///////////////// BRDF UTILS //////////////////////

float Fresnel(float cosI, float eta1, float eta2)
{
    float sinI = sqrt(1.0 - cosI * cosI);
    float beta = 1.0 - sqr(sinI * eta1 / eta2);

    if(beta < 0.0) { return 1.0; }

    float alpha = sqrt(beta);
    return (sqr((eta1 * cosI - eta2 * alpha) / (eta1 * cosI + eta2 * alpha)) +
            sqr((eta1 * alpha - eta2 * cosI) / (eta1 * alpha + eta2 * cosI))) * 0.5;
}

///////////////// LAMBERTIAN BRDF //////////////////////

#define kBxDFMaxPDF 1e6

float EvaluateLambertian()
{
    return 1. / kPi;
}

float SampleLambertian(vec2 xi, vec3 n, out vec3 o)
{        
    // Sample the Lambertian direction
    vec3 r = vec3(SampleUnitDisc(xi), 0.0f);
    r.z = sqrt(1.0 - sqr(r.x) - sqr(r.y));

    // Transform it to world space
    o = CreateBasis(n) * r;
    return r.z / kPi;
}

///////////////// PERFECT SPECULAR BRDF //////////////////////

float SamplePerfectSpecular(vec3 i, vec3 n, out vec3 o)
{
    o = reflect(-i, n);
    return kBxDFMaxPDF;
}

float SamplePerfectDielectric(float xi, vec3 i, vec3 n, float ior, out vec3 o, bool backfacing, inout float kickoff)
{
    // Figure out what kind of intersection we're doing
    vec2 eta = backfacing ? vec2(ior, 1.) : vec2(1., ior);

    // Calculate the Fresnel coefficient and associated vectors. 
    float F = Fresnel(dot(i, n), eta.x, eta.y);       
    if(xi > F)
    {
        o = refract(-i, n, eta.x / eta.y);
        kickoff *= -1.;
    }
    else
    {
       o = reflect(-i, n);
    }
    return kBxDFMaxPDF;
}

///////////////// MICROFACET BRDF //////////////////////

float D_GGX(vec3 m, vec3 n, float alpha)
{
    alpha *= alpha;
    float cosThetaM = clamp(dot(m, n), -1., 1.);
    float tan2ThetaM = 1. / sqr(cosThetaM) - 1.;
    return alpha * step(0.0f, cosThetaM) / 
           (kPi * pow4(cosThetaM) * sqr(alpha + tan2ThetaM));
}

float G1_GGX(vec3 v, vec3 m, vec3 n, float alpha)
{
    float cosThetaV = max(1e-10, dot(v, n));
    //float tan2ThetaV = sqr(tan(acos(cosThetaV)));
    float tan2ThetaV = 1. / sqr(cosThetaV) - 1.;
    return step(0.0f, dot(v, m) / cosThetaV) * 2. /
           (1.0f + sqrt(1.0 + sqr(alpha) * tan2ThetaV));
}

float G_GGX(vec3 i, vec3 o, vec3 m, vec3 n, float alpha)
{
     return G1_GGX(i, m, n, alpha) * G1_GGX(o, m, n, alpha);
}

float Weight_GGX(vec3 i, vec3 o, vec3 m, vec3 n, float alpha)
{
    #define kGGXWeightClamp 1e3
    return min(kGGXWeightClamp, abs(dot(i, m)) * G_GGX(i, o, m, n, alpha) / (abs(dot(i, n) * dot(m, n))));
}

float EvaluateMicrofacetReflectorGGX(in vec3 i, in vec3 o, in vec3 n, float alpha)
{
    #define kGGXPDFClamp 50.

    vec3 hr = normalize(sign(dot(i, n)) * (i + o));

    float pdf = G_GGX(i, o, hr, n, alpha) * D_GGX(hr, n, alpha) / (4. * abs(dot(i, n) * dot(o, n)));
    return min(kGGXPDFClamp, pdf);
}

float SampleMicrofacetReflectorGGX(vec2 xi, vec3 i, vec3 n, float alpha, out vec3 o, out float weight)
{        
    // Sample the microsurface normal with the GGX distribution
    float thetaM = atan(alpha * sqrt(xi.x) / sqrt(1.0f - xi.x));
    float phiM = kTwoPi * xi.y;
    float sinThetaM = sin(thetaM);
    vec3 m = CreateBasis(n) * vec3(cos(phiM) * sinThetaM, sin(phiM) * sinThetaM, cos(thetaM));
    o = reflect(-i, m);       

    weight = Weight_GGX(i, o, m, n, alpha);

    return (dot(o, n) <= 0.) ? 0. : EvaluateMicrofacetReflectorGGX(i, o, m, alpha);    
}

/////////////////////////

float D_Beckmann(vec3 m, vec3 n, float alpha)
{
    alpha *= alpha;
    float cosThetaM = clamp(dot(m, n), -1., 1.);
    float tan2ThetaM = 1. / sqr(cosThetaM) - 1.;
    return step(0.0f, dot(m, n)) / (kPi * alpha * pow4(cosThetaM)) * exp(-tan2ThetaM / alpha);
}

float G1_BeckmannExact(vec3 v, vec3 m, vec3 n, float alpha)
{
    float cosThetaV = max(1e-15, dot(v, n));
    float tan2ThetaV = 1. / sqr(cosThetaV) - 1.;
    float a = 1. / (alpha * tan2ThetaV);
    return step(0.0f, dot(v, m) / cosThetaV) * 2. /
           (1.0f + ErfApprox(a) + 1. / (a * kRootPi) * exp(-a*a));
}

float G1_Beckmann (vec3 v, vec3 m, vec3 n, float alpha)
{
    float cosThetaV = max(1e-15, dot(v, n));
    float tan2ThetaV = 1. / sqr(cosThetaV) - 1.;
    float a = 1. / (alpha * tan2ThetaV);
    float b = step(0.0f, dot(v, m) / cosThetaV);
    if(a > 1.6) { return b; }

    return b * a * (3.535 + a * 2.181) / (1. + a * (2.267 + a * 2.577));
}

float G_Beckmann(vec3 i, vec3 o, vec3 m, vec3 n, float alpha)
{
     return G1_Beckmann(i, m, n, alpha) * G1_Beckmann(o, m, n, alpha);
}

float Weight_Beckmann(vec3 i, vec3 o, vec3 m, vec3 n, float alpha)
{
    #define kBeckmannWeightClamp 50.
    return min(kBeckmannWeightClamp, abs(dot(i, m)) * G_Beckmann(i, o, m, n, alpha) / (abs(dot(i, n) * dot(m, n))));
}

float EvaluateMicrofacetReflectorBeckmann(in vec3 i, in vec3 o, in vec3 n, float alpha)
{
    #define kBeckmannPDFClamp 50.

    vec3 hr = normalize(sign(dot(i, n)) * (i + o));

    float pdf = G_Beckmann(i, o, hr, n, alpha) * D_Beckmann(hr, n, alpha) / (4. * abs(dot(i, n) * dot(o, n)));
    return min(kBeckmannPDFClamp, pdf);
}

float SampleMicrofacetReflectorBeckmann(vec2 xi, vec3 i, vec3 n, float alpha, out vec3 o, out float weight)
{        
    // Sample the microsurface normal with the Beckmann distribution
    float thetaM = atan(-alpha*alpha * log(1. - xi.x));
    float sinThetaM = sin(thetaM);
    float phiM = kTwoPi * xi.y;
    vec3 m = CreateBasis(n) * vec3(cos(phiM) * sinThetaM, sin(phiM) * sinThetaM, cos(thetaM));
    o = reflect(-i, m);       

    weight = Weight_Beckmann(i, o, m, n, alpha);

    return (dot(o, n) <= 0.) ? 0. : EvaluateMicrofacetReflectorBeckmann(i, o, m, alpha);    
}

vec3 Hue(float phi)
{
    float phiColour = 6.0 * phi;
    int i = int(phiColour);
    vec3 c0 = vec3(((i + 4) / 3) & 1, ((i + 2) / 3) & 1, ((i + 0) / 3) & 1);
    vec3 c1 = vec3(((i + 5) / 3) & 1, ((i + 3) / 3) & 1, ((i + 1) / 3) & 1);             
    return mix(c0, c1, phiColour - float(i));
}

vec4 Blend(vec4 rgba1, vec3 rgb2, float w2)
{
    // Assume that RGB values are premultiplied so that when alpha-composited, they don't need to be renormalised
    return vec4(mix(rgba1.xyz * rgba1.w, rgb2, w2) / max(1e-15, rgba1.w + (1. - rgba1.w) * w2),
                    rgba1.w + (1. - rgba1.w) * w2);
}

vec4 Blend(vec4 rgba1, vec4 rgba2)
{               
    // Assume that RGB values are premultiplied so that when alpha-composited, they don't need to be renormalised
    return vec4(mix(rgba1.xyz * rgba1.w, rgba2.xyz, rgba2.w) / max(1e-15, rgba1.w + (1. - rgba1.w) * rgba2.w),
                    rgba1.w + (1. - rgba1.w) * rgba2.w);
}

