vec2 EvaluateQuadraticSpline(in vec3 abcX, in vec3 abcY, in float t)
{
    return vec2(abcX.x * t*t + abcX.y * t + abcX.z, abcY.x * t*t + abcY.y * t + abcY.z);
}

vec2 EvaluateDQuadraticSpline(in vec3 abcX, in vec3 abcY, in float t)
{
    return vec2(2. * abcX.x * t + abcX.y, 2.0 * abcY.x * t + abcY.y);
}

bool QuadradicSplinePerpendicularPointApprox(in vec3 abcX, in vec3 abcY, in float margin, in vec2 xy, out float tPerp, out vec2 xyPerp, vec2 clip)
{
    float a0 = abcX.x, b0 = abcX.y, c0 = abcX.z;
    float d0 = abcY.x, e0 = abcY.y, f0 = abcY.z;
    float n0 = xy.x, m0 = xy.y;   

    vec4 P = vec4(-2.0*a0*a0 - 2.0*d0*d0, 
                  -3.0*a0*b0 - 3.0*d0*e0,
                  -b0*b0 - 2.0*a0*c0 - e0*e0 - 2.0*d0*f0 + 2.0*d0*m0 + 2.0*a0*n0,
                  -b0*c0 - e0*f0 + e0*m0 +  b0*n0);

    vec3 t, f;
    float b2ac4 = sqr(2.*P.y) - 4.0*(3.*P.x)*P.z;
    if(b2ac4 <= 1e-3 || abs(P.x) / max(1e-10, abs(P.y)) < 1.)
    {
        t.xz = vec2(-margin, 1. + margin);
        t.y = mix(t.x, t.z, 0.5);
    }
    else
    {
        b2ac4 = sqrt(b2ac4);
        float t0 = (-(2.*P.y) + b2ac4) / (2.0 * (3.*P.x));
        float t1 = (-(2.*P.y) - b2ac4) / (2.0 * (3.*P.x)); 

        t.x = t0-(t1-t0)*0.5;
        t.y = (t0+t1)*0.5;
        t.z = t1+(t1-t0)*0.5;    
    }

    #define Cubic(P, t) (P.w + (t) * (P.z + (t) * (P.y + (t) * P.x)))
    #define DCubic(P, t) (P.z + (t) * (2. * P.y + (t) * 3. * P.x))
    #define kNewtonIters 5
    for(int i = 0; i < kNewtonIters; ++i)
    {
        f = Cubic(P, t);
        t -= f / DCubic(P, t);       
    }
    t = clamp(vec3(clip.x), vec3(clip.y), t);
    f = Cubic(P, t);    

    xyPerp = vec2(kFltMax);
    float nearest = kFltMax;
    for(int idx = 0; idx < 3; ++idx)
    {
        if(abs(f[idx]) < 1e-5)
        {
            float t = clamp(t[idx], -margin, 1.0 + margin);
            vec2 perp = vec2(abcX.x * t*t + abcX.y * t + abcX.z,
                            abcY.x * t*t + abcY.y * t + abcY.z);                        

            float dist = length2(xy - perp);
            if(dist < nearest)
            {
                nearest = dist;
                xyPerp = perp;
                tPerp = t;
            }            
       }
    }

    return true;
}


