#define kInvalidMaterial -1
#define kMatEmitter 0
#define kMatRoughSpecular 1
#define kMatRoughDielectric 2
#define kMatPerfectSpecular 3
#define kMatPerfectDielectric 4
#define kMatLambertian 5
#define kMatCompound 6

float PowerHeuristic(float pdf1, float pdf2)
{
    return saturate(sqr(pdf1) / max(1e-10, sqr(pdf1) + sqr(pdf2)));
}

float SampleEmitter(in Ray incident, out Ray extant, in HitCtx hit, in Transform emitterTrans, in vec3 xi, inout vec3 L)
{
    vec3 i = -incident.od.d;

#ifdef kUseQuadEmitter
    float emitterPdf = (xi.z < 0.5) ? SampleQuadLight(incident, extant, hit, emitterTrans, xi.xy) :
                                      SampleEnvLight(incident, extant, hit, xi.xy, L);
#else                                 
    float emitterPdf = SampleEnvLight(incident, extant, hit, xi.xy, L);
#endif

    if(emitterPdf <= 0.) { return 0.; }            

    float bxdfPdf;
    switch(hit.matID) 
    {
        case kMatLambertian:
        {
            bxdfPdf = EvaluateLambertian(); 
            break;
        }
        case kMatRoughSpecular:
        {
            bxdfPdf = EvaluateMicrofacetReflectorGGX(i, extant.od.d, hit.n, hit.alpha);
            break;
        }
        default:
            L += kRed * 1e3; return 0.; // Should never be here!
    }

    // Lambert cosine factor
    bxdfPdf *= dot(extant.od.d, hit.n);    

    extant.weight *= 2. * bxdfPdf * PowerHeuristic(emitterPdf, bxdfPdf);

#ifdef kUseQuadEmitter
    extant.weight *= 2.;
#endif

    return emitterPdf;
}

float SampleBxDF(in Ray incident, out Ray extant, in HitCtx hit, in Transform emitterTrans, in vec3 xi, in bool useMis, inout vec3 L)
{
    vec3 o;
    float bxdfPdf, brdfWeight = 1.;
    switch(hit.matID) 
    {    
        case kMatLambertian:
        {
            bxdfPdf = SampleLambertian(xi.xy, hit.n, o); 
            break;
        }
        case kMatPerfectSpecular:
        {
            bxdfPdf = SamplePerfectSpecular(-incident.od.d, hit.n, o);
            break;
        }
        case kMatPerfectDielectric:
        {
            bxdfPdf = SamplePerfectDielectric(xi.y, -incident.od.d, hit.n, hit.alpha, o, IsBackfacing(incident), hit.kickoff);
            if(IsBackfacing(incident))
            {
                //vec3 hue = mix(kOne, kOne - Hue(0.6), 0.8);
                //incident.weight *= exp(-incident.tNear * kOne * 100.);
            }
            break;
        }
        case kMatRoughSpecular:
        {
            bxdfPdf = SampleMicrofacetReflectorGGX(xi.xy, -incident.od.d, hit.n, hit.alpha, o, brdfWeight);
            break;
        }
    }    

    if(bxdfPdf <= 0.) { return 0.; }

    CreateRay(extant, PointAt(incident), o, hit.n * hit.kickoff, incident.weight * brdfWeight, incident.depth + 1, InheritFlags(incident)); 

    if(!(hit.matID == kMatPerfectSpecular || hit.matID == kMatPerfectDielectric)) { extant.flags |= kFlagsScattered; }

    if(useMis)
    {
#ifdef kUseQuadEmitter
        float emitterPdf = (xi.z < 0.5) ? EvaluateQuadLight(extant, hit, emitterTrans) :
                                          EvaluateEnvLight(extant, hit); 
#else
        float emitterPdf = EvaluateEnvLight(extant, hit); 
#endif

        extant.weight *= 2. * PowerHeuristic(bxdfPdf, emitterPdf);
        extant.flags |= kFlagsDirectSampleBxDF;

#ifdef kUseQuadEmitter
        extant.weight *= 2.;
#endif

    }

    return bxdfPdf;
}

#define kGenerateNothing 0
#define kGeneratedDirect 1
#define kGeneratedIndirect 2

#define kModePathTraced 0
#define kModeNEE 1

int Shade(in Ray incident, inout Ray indirectRay, inout Ray directRay, in HitCtx hit, inout RenderCtx renderCtx, Transform emitterTrans, int renderMode, inout vec3 L)
{             
    // Generate some random numbers
    float5 xi;
    xi = QRand5(renderCtx.rng, uint((1 + incident.depth) * 5));
    float xiSplit = fract(OrderedDither(renderCtx.xyScreen) + float(iFrame) / 16.);

    if(hit.matID == kMatCompound)
    {
        hit.matID = (xiSplit < 0.1) ? kMatPerfectSpecular : kMatLambertian;
    }

    incident.weight *= hit.albedo;

    if(hit.matID == kMatPerfectSpecular || hit.matID == kMatPerfectDielectric)  { renderMode = kModePathTraced; }

    int genFlags = 0;
    if(renderMode == kModeNEE)
    {
        if(xiSplit < 0.5)
        {   
            if(SampleEmitter(incident, directRay, hit, emitterTrans, vec3(xi[0], xi[1], xi[2]), L) > 0.)
            {
                genFlags |= kGeneratedDirect; 
            }
        }
        else
        {        
            if(SampleBxDF(incident, directRay, hit, emitterTrans, vec3(xi[0], xi[1], xi[2]), true, L) > 0.)
            {
                genFlags |= kGeneratedDirect;
            }            
        }
    }

    if(/*renderMode == kModePathTraced && */SampleBxDF(incident, indirectRay, hit, emitterTrans, vec3(xi[2], xi[3], 0.), false, L) > 0.)
    {
        genFlags |= kGeneratedIndirect;
    } 

    return genFlags;
} 

float Grid2D(vec2 uv, float thickness)
{
    return step(thickness, fract(uv.x)) * step(thickness, fract(uv.y));
}

// Peturb the normal using the tangent space in the hit context
vec3 PerturbNormal(inout HitCtx hit, sampler2D sampler, float alpha, float delta)
{
    alpha = sign(alpha) * sqr(alpha);

    float dpdu = luminance(texture(sampler, hit.uv + vec2(-delta, 0.), 0.).xyz - texture(sampler, hit.uv + vec2(delta, 0.), 0.).xyz) / (2. * delta);
    float dpdv = luminance(texture(sampler, hit.uv + vec2(0., -delta), 0.).xyz - texture(sampler, hit.uv + vec2(0., delta), 0.).xyz) / (2. * delta);

    return normalize(hit.n + (hit.tangent * dpdu + hit.cotangent * dpdv) * alpha);    
}

// Evaluates the texture using a triplanar mapping
vec3 Triplanar(vec3 p, vec3 n, float scale, int type, sampler2D sampler)
{
    p *= scale;
    vec3 rgbX = texture(sampler, mod(abs(p.yz), vec2(1.)), 0.).xyz;
    vec3 rgbY = texture(sampler, mod(abs(p.xz), vec2(1.)), 0.).xyz;
    vec3 rgbZ = texture(sampler, mod(abs(p.xy), vec2(1.)), 0.).xyz;

    vec3 w = pow(abs(n), vec3(2.));
    w /= sum(w);    

    if(type == 0)
    {
        return rgbX * w.x + rgbY * w.y + rgbZ * w.z;
    }
    else
    {    
        float L = sin01(kTwoPi * 2. * luminance(rgbX * w.x + rgbY * w.y + rgbZ * w.z));
        return kOne * L / (1. + exp(-8. * mix(-1., 1., L)));
    }
}

// Perturbs the surface normal using a triplanar texture
vec3 PerturbNormalTriplanar(vec3 p, inout HitCtx hit, float alpha, float delta, float scale, int type, sampler2D sampler)
{    
    alpha = sign(alpha) * sqr(alpha);
    delta /= scale;

    mat3 basis = CreateBasis(hit.n);
    float dpdu = luminance(Triplanar(p + basis[0] * -delta, hit.n, scale, type, sampler) - 
                           Triplanar(p + basis[0] * delta, hit.n, scale, type, sampler)) / (2. * delta);
    float dpdv = luminance(Triplanar(p + basis[1] * -delta, hit.n, scale, type, sampler) - 
                           Triplanar(p + basis[1] * delta, hit.n, scale, type, sampler)) / (2. * delta);

    return normalize(hit.n + (basis[0] * dpdu + basis[1] * dpdv) * alpha);    
}

int Trace(inout Ray ray, out HitCtx hit, bool indirectLambert, in float xi, out float FMin)
{
    Transform transform;
    hit.matID = kInvalidMaterial;  
    hit.objID = kInvalidMaterial;
    float bumpMagnitude = 0.;
    float bumpDelta = 1e-3;
    float bumpScale = 1.;
    int bumpType = 0;
    bool triplanarAlbedo = false;

//#ifndef kSimpleMode

    // Extruded spline SDF
    transform = CompoundTransform(vec3(0., 0.25, 0.) + kSDFOffset, vec3(0., 0., 0.), kSDFScale);        
    if(RaySDF(ray, hit, transform, xi, FMin))
    {
        hit.objID = 0;
        hit.matID = kMatRoughSpecular; 
        hit.alpha = 0.05;
        hit.albedo = kOne;

        bumpMagnitude = 0.02;
        //bumpDelta = 1e-3;
        bumpScale = 10.;
        bumpType = 1;
    }

//#endif

#ifdef kUseQuadEmitter
    // Emitter plane
    if(ray.depth > 0)
    {
        transform = CompoundTransform(kQuadEmitterPos, kQuadEmitterRot, kQuadEmitterSca);
        if(RayPlane(ray, true, hit, transform))
        {
            hit.objID = 1;
            hit.matID = kMatEmitter;        
        }
    }
#endif

    // Spheres with different matertials
    #define kNumSpheres 7
    for(int sphereIdx = 0; sphereIdx < kNumSpheres; ++sphereIdx)
    {
        float sphereDelta = float(sphereIdx) / float(kNumSpheres);
        float phi = kTwoPi * sphereDelta;
        transform = CompoundTransform(vec3(cos(phi), 0., sin(phi)) * 0.5, vec3(0., 0., 0.), 0.15);

        if(RaySphere(ray, hit, transform, false))
        {
            //hit.n = PerturbNormal(hit, iChannel2, 0.1, 0.001);

            //bumpMagnitude = mix(0.01, 0.15, sqr(1. - sphereDelta));
            //bumpScale = mix(10., 2., pow(1. - sphereDelta, 1.5));
            bumpMagnitude = 0.1;
            bumpScale = 1.;
            bumpDelta = 1e-3;
            bumpType = 0;

            hit.albedo = mix(kOne, Hue(sphereDelta), 0.5);

            triplanarAlbedo = false;
            switch(sphereIdx) 
            {
            case 0:
                hit.matID = kMatPerfectSpecular; 
                bumpMagnitude = 0.02;
                bumpScale = 2.;
                bumpType = 1;
                break;
            case 1:
                hit.matID = kMatPerfectDielectric; 
                hit.alpha = 1.5;
                bumpMagnitude = 0.;
                break;
            case 2:
                hit.matID = kMatLambertian;
                triplanarAlbedo = true;
                break;
            case 3:
                hit.matID = kMatCompound;
                hit.alpha = 0.2;
                break;
            default:
                hit.matID = kMatRoughSpecular;
                hit.alpha = mix(0.01, 0.5, sqr(float(sphereIdx - 4) / float(kNumSpheres - 4)));

                break;
            }             
        }
    }

    // Ground plane
    transform = CompoundTransform(vec3(0., -0.15, 0.), vec3(-0.5 * kPi, 0., 0.), 2.);
    if(RayPlane(ray, false, hit, transform))
    {

        hit.objID = 2;
        hit.matID = kMatRoughSpecular;       

        hit.alpha = mix(0.05, 0.5, sqr(texture(iChannel2, hit.uv, -1.0).x));
        hit.albedo = kOne * 0.75;

        bumpMagnitude = 0.05;
        bumpScale = 1.; 
    }

    // If the material has a bump texture...
    if(bumpMagnitude > 0.)
    {    
        hit.n = PerturbNormalTriplanar(PointAt(ray) + vec3(100.), hit, bumpMagnitude, 0.001, bumpScale, bumpType, iChannel2);
    }

    // If the material has textured albedo... 
    if(triplanarAlbedo)
    {
        float L = luminance(Triplanar(PointAt(ray) + vec3(100.), hit.n, 1., 1, iChannel2) * 2.);
        L = sin01(kTwoPi * 2. * L);
        L = 1. / (1. + exp(-8. * mix(-1., 1., L)));        
        hit.albedo *= kOne * mix(0.1, 0.8, L);
    }

    // Make all materials diffuse Lambert
    //if(hit.matID != kInvalidMaterial && hit.matID != kMatEmitter)  hit.matID = kMatLambertian;  

    return hit.matID;
}

vec3 GetCameraPos()
{
    vec2 uv = texelFetch(iChannel0, ivec2(2, 0), 0).xy;
    float phi = kTwoPi * mix(-1., 1., uv.x / iResolution.x);
    float theta = kHalfPi * clamp(uv.y / iResolution.y, 0.01, 0.99);

    //return vec3(cos(cameraPhi), 0.5, sin(cameraPhi)) * mix(2., .05, uv.y / iResolution.y);
    return vec3(cos(phi) * sin(theta), cos(theta), sin(phi) * sin(theta)) * 1.5;
}

vec3 GetCameraLookAt()
{
    vec2 uv = texelFetch(iChannel0, ivec2(3, 0), 0).xy / iResolution.x;
    return vec3(uv.x, 0., uv.y);
}

bool UpdateState(ivec2 xyPixel, inout vec2 xyScreen, vec4 mouse, vec4 samplerState, vec3 cameraPos, inout vec4 rgba)
{ 
    #define kInitMouse (iResolution.xy * vec2(0.15, 0.5))

    uint stateBits = uint(samplerState.y);

    // State
    if(xyPixel.y == 0 && xyPixel.x < 5)
    {
        rgba = texelFetch(iChannel0, ivec2(xyScreen), 0);
        vec4 mouseState = texelFetch(iChannel0, ivec2(0), 0);

        // Mouse state
        if(xyPixel.x == 0)
        {        
            // Update the anchor point when the mouse state changes
            if(mouse.z != rgba.w) { rgba.xy = mouse.xy; }
            rgba.z = rgba.w;
            rgba.w = mouse.z;            
        }
        // Frame state
        else if(xyPixel.x == 1)
        {
            rgba = vec4(samplerState);
        }

        if(!IsMouseInConfig(mouse.xy, iResolution.xy, stateBits))
        {
            // Camera position
            if(xyPixel.x == 2)
            {           
                // Avoid flickering by not doing updates during mouse-down frames or config key down (stored in samplerState.y)
                if(!AnyCameraKeyDown(stateBits) && mouse.w <= 0.)
                {
                    // Set the reference point as the sum of the anchor plus the delta between the mouse anchor and mouse cursor
                    rgba.xy = rgba.zw + (mouse.xy - mouseState.xy);

                    // If the mouse button has been lifted, update the anchor point
                    if((mouse.z <= 0. && mouseState.w > 0.))
                    {
                        rgba.zw = rgba.xy;                    
                    }   

                    // Clamp in the y axis
                    rgba.yw = clamp(rgba.yw, vec2(0), vec2(iResolution.y - 1.));

                }

                if(iFrame == 0 || int(mouse.x) <= 0 || int(mouse.y) <= 0) { rgba.xy = kInitMouse; }
            }

             // Camera look-at
            else if(xyPixel.x == 3) 
            {           
                // Avoid flickering by not doing updates during mouse-down frames or config key down (stored in samplerState.y)
                if(IsWDown(stateBits) && mouse.w <= 0.)
                {
                    cameraPos.xz = normalize(cameraPos.xz);

                    // Set the reference point as the sum of the anchor plus the delta between the mouse anchor and mouse cursor
                    rgba.xy = rgba.zw + 
                              2. * (cameraPos.xz * (mouse.y - mouseState.y) + 
                                    vec2(-cameraPos.z, cameraPos.x) * (mouse.x - mouseState.x));


                    // If the mouse button has been lifted, update the anchor point
                    if((mouse.z <= 0. && mouseState.w > 0.)) { rgba.zw = rgba.xy; }   

                }

                if(iFrame == 0 || int(mouse.x) <= 0 || int(mouse.y) <= 0) { rgba.xy *= 0.; }            
            }
             // Camera DoF
            else if(xyPixel.x == 4)
            {           
                // Avoid flickering by not doing updates during mouse-down frames or config key down (stored in samplerState.y)
                if(IsEDown(stateBits) && mouse.w <= 0.)
                {
                    // Set the reference point as the sum of the anchor plus the delta between the mouse anchor and mouse cursor
                    rgba.xy = rgba.zw + (mouse.xy - mouseState.xy);

                    // If the mouse button has been lifted, update the anchor point
                    if((mouse.z <= 0. && mouseState.w > 0.))
                    {
                        rgba.zw = rgba.xy;                    
                    }   

                }

                if(iFrame == 0 || int(mouse.x) <= 0 || int(mouse.y) <= 0) { rgba.xy = vec2(0); }            
            }
        }

        return true;       
    }

    return false;
}

void mainImage( out vec4 rgba, in vec2 xyScreen )
{
    rgba = vec4(0.);

    vec4 samplerState = texelFetch(iChannel1, kPDF2State, 0); 
    uint stateBits = uint(samplerState.y);
    vec3 cameraLookAt = GetCameraLookAt();
    vec3 cameraPos = GetCameraPos();
    vec4 mouse = iMouse;    
    ivec2 xyPixel = ivec2(xyScreen);
    if(iFrame == 0 || int(mouse.x) <= 0 || int(mouse.y) <= 0) { mouse.xy = kInitMouse; }

    if(UpdateState(xyPixel, xyScreen, mouse, samplerState, cameraPos, rgba)) { return; }

    // Idle for as many frames as it takes to build the environment sampler
    if(int(samplerState.x) <= 4 + kPDF2PhiSteps + kPDF2ThetaSteps) 
    { 
        if(IsADown(stateBits)) { rgba = texelFetch(iChannel0, ivec2(xyScreen), 0); }
        return; 
    }    

    rgba *= 0.;     
    if(iMouse.z <= 0.)
    {
        rgba = texelFetch(iChannel0, ivec2(xyScreen), 0);
    }
    //rgba *= 0.;

    RenderCtx renderCtx;
    renderCtx.xyScreen = ivec2(xyScreen);
    float5 xi;
    renderCtx.rng.x = 98796235u;
    renderCtx.rng.y = HashOf(uint(xyScreen.x), uint(xyScreen.y)) + uint(iFrame);
    xi = Rand5(renderCtx.rng);
    xi[4] = HaltonBase2(renderCtx.rng.y);    

    Transform emitterTrans;
#ifdef kUseQuadEmitter
    emitterTrans = CompoundTransform(kQuadEmitterPos, kQuadEmitterRot, kQuadEmitterSca);
#endif

    vec2 uvView = ScreenToNormalisedScreen(xyScreen + vec2(xi[0], xi[1]), iResolution.xy);  

    cameraPos += cameraLookAt;    

    float camDist = length(cameraLookAt - cameraPos);
    float focus = texelFetch(iChannel0, ivec2(4, 0), 0).y / iResolution.y;
    cameraLookAt = cameraPos + (cameraLookAt - cameraPos) * max(0., 1. + focus);


    //Ray indirectRay = CreatePinholeCameraRay(uvView, cameraPos, vec3(0., -0.1, -0.), 40.);
    Ray indirectRay = CreatePerspectiveCameraRay(uvView, cameraPos, cameraLookAt, 0.05, 1.5, vec4(xi[0], xi[1], xi[2], xi[3]), iResolution.xy);  

    Ray directRay;
    Ray ray;
    int genFlags = kGeneratedIndirect;
    HitCtx hit;
    vec3 L = kZero;

    // Left half of screen = path traced reference. Right half = path tracing + NEE
    int renderMode = kModeNEE;//(xyScreen.x < iResolution.x * 0.5) ? kModePathTraced : kModeNEE;        

    #define kMaxPathDepth 5
    #define kMaxIterations 10
    for(int rayIdx = 0; rayIdx < kMaxIterations && genFlags != kGenerateNothing; ++rayIdx)
    {                
        if((genFlags & kGeneratedDirect) != 0) ray = directRay; else ray = indirectRay;        

        // ***** WEIGHT CLAMP ******
        //ray.weight = clamp(ray.weight, kZero, kOne * 10.);

        if(ray.depth >= kMaxPathDepth) { continue; }

        float rayFMin = 0.;
        if(Trace(ray, hit, false, xi[4], rayFMin) == kInvalidMaterial)
        {
            if(IsDirectSampleEnv(ray))
            {
                L += ray.weight; 
            }
            else if(renderMode == kModePathTraced || !IsScattered(ray)) // Environment light is importance sampled, so only evaluate it pure path tracing mode
            {
                vec3 envRadiance;
                if(EvaluatePDF2(iChannel1, vec2(atan2(ray.od.d.z, ray.od.d.x) / kTwoPi, SafeAcos(-ray.od.d.y) / kPi), envRadiance) > 0.)
                {
                    L += ray.weight * envRadiance * kSkylightPower;
                }
            }

            break;
        }            

        if(IsSpotlightEnabled(stateBits))
        {
            ray.weight *= exp(-length2(PointAt(ray) * 0.5));
        }

        if(IsDirectSampleEnv(ray)) { genFlags &= ~kGeneratedDirect; continue; }

#ifdef kSimpleMode
            L = (hit.n * 0.5 + 0.5); 
            break;        
#endif

        if((genFlags & kGeneratedDirect) != 0)
        {
            if(hit.matID == kMatEmitter && !IsBackfacing(ray))
            {
                // If this sample is a light ray, all we need to know is whether or not it hit the light. 
                // If it did, just accumulate the weight which contains the radiant energy from the light sample.       
               L += ray.weight;
            }
            genFlags &= ~kGeneratedDirect; 
        }
        else if((genFlags & kGeneratedIndirect) != 0)
        {              
            if(hit.matID == kMatEmitter)
            {
                // Emitters don't reflect light, so simply accumulate its radiance and we're done
                if(!IsBackfacing(ray) && (!IsScattered(ray) || renderMode == kModePathTraced))
                {
                    L += kQuadEmitterRadiance * ray.weight;
                }
                genFlags = 0;
            }
            else
            {            
                // Otherwise, shade indirect rays
                genFlags = Shade(ray, indirectRay, directRay, hit, renderCtx, emitterTrans, renderMode, L);
            }
        }
    }            

    // Clamp the values a bit to reduce bloom shimmer
    #define kSplatClamp 20.
    float LMax = cwiseMax(L);
    if(LMax > kSplatClamp) { L *= kSplatClamp / LMax; }

    //if(kAutoRotate) { rgba *= (iMouse.z <= 0.) ? 0.97 : 0.7; }
    if(iMouse.z > 0. || texelFetch(iChannel0, ivec2(0), 0).w > 0.) { rgba *= 0.f; }
    rgba += vec4(L * 2., 1.);

    #ifdef kSquelchNaNs
        // NaN clipping (not sure why this is a problem)
        for(int c = 0; c < 4; ++c) if(isinf(rgba[c]) || isnan(rgba[c])) rgba = vec4(L, 1.);
    #endif

    /*vec2 uv = vec2(3., 6.) * xyScreen / iResolution.xy;
    if(uv.y < 1. && uv.x < 1.)
    {
        EvaluatePDF2(iChannel1, vec2(0., 0.5) + vec2(1., 0.5) * uv, rgba.xyz);
        rgba.w = 1.;
    }*/
}

// LENS BLOOM PASS

/*
    SDF acceleration structure
*/

vec2 ScreenToView(vec2 xy)
{
    vec2 uv = ((xy / kPathAccelDims.xy) - vec2(0.5, 0.));
    return uv * vec2(1., kPathAccelDims.y / kPathAccelDims.x) + vec2(0.5, 0.);
}

vec4 BuildSDFAcceleration(in vec2 xyScreen )
{      
    vec4 rgba = vec4(0.);
    vec2 xyAccel = xyScreen - vec2(kPathAccelOffset);

    if(xyAccel.x >= kPathAccelDims.x || xyAccel.y >= kPathAccelDims.y) { return rgba; }    

    if(iFrame == 4)
    {
        vec4 texel = texelFetch(iChannel1, ivec2(xyScreen), 0);
        vec4 sorted = vec4(texel[0], -1.0, -1.0, -1.0); 

        int i = 1;
        for(int u = 1; u < 4; ++u)
        {
            int v = u - 1;
            for(; v >= 0; --v)
            {
                if(texel[u] == texel[v]) { break; }
            }
            if(v == -1) { sorted[i++] = texel[u]; }
        }

        return sorted;        
        return rgba;
    }    
    else if(iFrame > 4)
    {
        return texelFetch(iChannel1, ivec2(xyScreen), 0);
    }

    rgba = (iFrame == 0) ? vec4(0.0) : texelFetch(iChannel1, ivec2(xyScreen), 0);

    vec2 xyView = ScreenToView(xyAccel + vec2(float(iFrame % 2), float(iFrame / 2)) * 1.0 - .0);
    xyView -= 0.5 * vec2(1., kPathAccelDims.y / kPathAccelDims.x);

    float distNear2 = kFltMax;
    int idxNear;
    for(int splineIdx = 0; splineIdx < kNumSplines; ++splineIdx)
    {             
        float tPerp;
        vec2 xyPerp;
        if(QuadradicSplinePerpendicularPointApprox(points[splineIdx*2], points[splineIdx*2+1], 0.02, xyView, tPerp, xyPerp, vec2(-kFltMax, kFltMax)))
        {
            float dist2 = length2(xyPerp - xyView);
            if(dist2 < distNear2)
            {
                idxNear = splineIdx;
                distNear2 = dist2;
            }
        }
    } 

    rgba[iFrame % 4] = float(idxNear);
    return rgba;
}

void mainImage( out vec4 rgba, in vec2 xyScreen )
{   
    rgba = vec4(0.0);

    if(int(xyScreen.x) >= kPathAccelOffset.x && int(xyScreen.y) >= kPathAccelOffset.y)
    {
        rgba = BuildSDFAcceleration(xyScreen);
    }
    else if(IsToggleSet(kIDBloom, iChannel3))
    {        
        vec3 L0 = SeparableBlurDown(ivec2(xyScreen), ivec2(iResolution), vec2(0.05), vec3(1.5, 1.8, 2.4), iChannel0); 
        vec3 L1 = SeparableBlurDown(ivec2(xyScreen), ivec2(iResolution), vec2(0.1), vec3(1.0, 1.8, 2.4), iChannel0); 

        rgba.x = uintBitsToFloat(_packHalf2x16(L0.xy));
        rgba.y = L0.z;
        rgba.z = uintBitsToFloat(_packHalf2x16(L1.xy));
        rgba.w = L1.z;
    }
}

// ENVIRONMENT SAMPLER PMF CONSTRUCTION

vec3 EvaluateLatLong(sampler2D sampler, vec2 xyScreen)
{     
    vec2 latlong = xyScreen / vec2(kPDF2Width, kPDF2Height);
    latlong.y = 1. - latlong.y;

    if(latlong.y > 0.5)
    {
        return kZero;
    }
    else
    {
        vec2 cart = vec2(cos(latlong.x * kTwoPi), sin(latlong.x * kTwoPi)) * latlong.y * (0.49 * 2.);
        return texture(iChannel2, (vec2(0.5) + cart) * vec2(iResolution.y / iResolution.x, 1.), 0.).xyz;
    }   

}

void mainImage( out vec4 rgba, in vec2 xyScreen )
{    
    rgba = vec4(0.);

    // x: normalised PMF
    // y: normalised CMF  
    // zw: half-precision RGB environment value    

    if(int(xyScreen.x) == kPDF2State.x && int(xyScreen.y) == kPDF2State.y)
    {        
        rgba = texelFetch(iChannel0, ivec2(xyScreen), 0);
        if(iFrame == 0) { rgba = vec4(0.); }        

        bool isQDown = IsKeyDown(iChannel3, KEY_Q);
        bool isADown = IsKeyDown(iChannel3, KEY_A);
        rgba.x = (iFrame == 0 || (iMouse.z > 0. && IsMouseInConfig(iMouse.xy, iResolution.xy, uint(rgba.y)))) ? 0. : texelFetch(iChannel0, ivec2(xyScreen), 0).x + 1.;

        uint keyBits = (uint(isQDown) << 0) |
                       (uint(isADown) << 1) |
                       (uint(IsKeyDown(iChannel3, KEY_W)) << 2) |
                       (uint(IsKeyDown(iChannel3, KEY_E)) << 3) |
                       (uint(IsToggleSet(kIDSpotlight, iChannel2)) << 4);
        //rgba.y = uintBitsToFloat(keyBits);
        rgba.y = float(keyBits) + 0.5;

        return;    
    }    

    // Localise coordinates
    int x = int(xyScreen.x) - kPDF2Offset.x;
    int y = int(xyScreen.y) - kPDF2Offset.y;

    if(x >= kPDF2Width + 1 || y >= kPDF2Height) { return; }    

    int frame = int(texelFetch(iChannel0, kPDF2State, 0).x);
    rgba = (frame == 0) ? vec4(0.) : texelFetch(iChannel0, ivec2(xyScreen), 0);

    // Build the CDF iteratively over a few frames. We could simply brute-force integrate it all at once,
    // but this would stall the shader for big CDFs. Accept a small delay to save on compute time.
    if(frame == 0)
    {    
        //float phi = kTwoPi * xyScreen.x / float(kPDF2Width);
        float theta = kPi * xyScreen.y / float(kPDF2Height);           
        //rgba = vec4(cwiseMax(EvaluateCubemap(iChannel1, theta, phi)));
        rgba *= 0.;
        if(theta > kHalfPi)
        {
            rgba = vec4(cwiseMax(EvaluateLatLong(iChannel2, xyScreen)));
            rgba.w *= sin(theta);
            rgba.y = 0.;        
        }
    }
    else if(frame == 1)
    {
        // Integrate the area of each logical cell in the grid
        rgba.y = (x == 0) ? 0. : (0.5 * (texelFetch(iChannel0, kPDF2Offset + ivec2(x, y), 0).x + texelFetch(iChannel0, kPDF2Offset + ivec2(x - 1, y), 0).x));
        rgba.y *= sin(kPi * float(y) / float(kPDF2Height));

    }
    else if(frame < 2 + kPDF2PhiSteps)
    {   
        int localFrame = frame - 2;

        // Iterative reduce. Needs O(log n) texture taps instead O(n)
        int subIdx = x >> localFrame;        
        if((subIdx & 1) == 1)
        {
            uint subCDFPrev = (uint(x) & ~((1u << localFrame) - 1u)) - 1u;
            if(subCDFPrev != 0xffffffffu)
            {
                rgba.yw += texelFetch(iChannel0, kPDF2Offset + ivec2(subCDFPrev, y), 0).yw;   
            }
        }       
    }
    else if(frame == 2 + kPDF2PhiSteps)
    {
        if(x == kPDF2Width)
        {
            // Integrate the area of each logical cell in the grid
            rgba.y = (y == 0) ? 0. : (0.5 * (texelFetch(iChannel0, kPDF2Offset + ivec2(x - 1, y), 0).y + 
                                             texelFetch(iChannel0, kPDF2Offset + ivec2(x - 1, y - 1), 0).y));
            rgba.xw = texelFetch(iChannel0, kPDF2Offset + ivec2(x - 1, y), 0).yw;
        }
    }
    else if(frame < 3 + kPDF2PhiSteps + kPDF2ThetaSteps)
    {
        int localFrame = frame - (3 + kPDF2PhiSteps);

        if(x == kPDF2Width)
        {                        
            int subIdx = y >> localFrame;        
            if((subIdx & 1) == 1)
            {
                uint subCDFPrev = (uint(y) & ~((1u << localFrame) - 1u)) - 1u;
                if(subCDFPrev != 0xffffffffu)
                {
                    rgba.yw += texelFetch(iChannel0, kPDF2Offset + ivec2(kPDF2Width, subCDFPrev), 0).yw;          
                }
            }       
        }
    }
      // Normalise the theta PDF
    else if(frame == 3 + kPDF2PhiSteps + kPDF2ThetaSteps)
    {
        if(x == kPDF2Width)
        {
            float norm = max(1e-10, texelFetch(iChannel0, kPDF2Offset + ivec2(kPDF2Width, kPDF2Height - 1), 0).y);
            rgba.x /= norm;
            rgba.y /= norm;
            rgba.z = texelFetch(iChannel0, ivec2(kPDF2Width - 2, y), 0).y;
        }
    }
    // Normalise the phi PDFs
    else if(frame == 4 + kPDF2PhiSteps + kPDF2ThetaSteps)
    {
        if(x < kPDF2Width)
        {
            // Normalise the values
            float rowNorm = max(1e-10, texelFetch(iChannel0, kPDF2Offset + ivec2(kPDF2Width - 1, y), 0).y);
            float mapNorm = max(1e-10, texelFetch(iChannel0, kPDF2Offset + ivec2(kPDF2Width, kPDF2Height - 1), 0).w);
            rgba.y /= rowNorm;
            rgba.x *= float(kPDF2Width * kPDF2Height) / mapNorm;
            rgba.x *= 2. / kPi;

            // Re-evaluate the environment and encode it             
            vec3 rgb = EvaluateLatLong(iChannel2, xyScreen);

            // If the normalise toggle is set, scale the 
            if(IsToggleSet(kIDNormalise, iChannel2))
            {
                rgb *= float(kPDF2Width * kPDF2Height) / mapNorm;
            }

            rgba.z = uintBitsToFloat(_packHalf2x16(rgb.xy));
            rgba.w = rgb.z;
        }
    }

}

#define kMaxKernelWidth 500
#define iRes iResolution
#define kUseTexture 1

#define kdPdXY (1. / iRes.y)

#define kStateFree 0.
#define kStateDragging 1.

#define kCtrlPointRadius 10.
#define kDialRadius 0.06
#define kDialThickness 3.
#define kIconThickness (kDialThickness * 0.8)

// Loads the position of the node relative to its parents (if any)
vec4 LoadState(int idx, sampler2D sampler)
{
    return texelFetch(sampler, ivec2(idx, 0), 0);
}

vec2 ScreenToView(vec2 xyScreen, vec3 iRes)
{
    return (xyScreen - iRes.xy * 0.5) / min(iRes.x, iRes.y);
}


// *******************************************************************************************************
//    2D SVG
// *******************************************************************************************************

float SDFLine(vec2 p, vec2 v0, vec2 v1, float thickness, float dPdXY)
{
    v1 -= v0;
    float t = saturate((dot(p, v1) - dot(v0, v1)) / dot(v1, v1));
    vec2 perp = v0 + t * v1;
    return saturate((thickness - length(p - perp)) / dPdXY);
}


float SDFDashedLine(vec2 p, vec2 v0, vec2 v1, float thickness, float hashFreq, float hashDensity, float dPdXY)
{
    v1 -= v0;
    hashFreq *= length(v1) / dPdXY;
    float t = saturate((dot(p, v1) - dot(v0, v1)) / dot(v1, v1)) * hashFreq;
    float f = fract(t);   
    if(f > hashDensity)
    {
        if(f > 1. - ((1. - hashDensity) * 0.5)) t += 1. - f;
        else t -= f - hashDensity;
    }

    vec2 perp = v0 + (t / hashFreq) * v1;
    return saturate((thickness - length(p - perp)) / dPdXY);
}

float SDFQuad(vec2 p, vec2 v[4], float thickness, float dPdXY)
{
    float c = 0.0;
    for(int i = 0; i < 4; i++)
    {
        c = max(c, SDFLine(p, v[i], v[(i+1)%4], thickness, dPdXY)); 
    }

    return c;
}

float SDFCircle(vec2 p, vec2 o, float r, float dPdXY)
{
    return saturate((1. - length(p - o) / r) * (r / dPdXY));
}

float SDFSquircle(vec2 p, vec2 o, vec2 b, float r, float dPdXY)
{
    p -= o;
    p.x = sign(p.x) * max(0., abs(p.x) - b.x * 0.5); 
    p.y = sign(p.y) * max(0., abs(p.y) - b.y * 0.5); 

    return saturate((1. - length(p) / r) * (r / dPdXY));
}

float SDFHemicircle(vec2 p, vec2 o, float r, vec2 plane, float dPdXY)
{
    p -= o;
    return (dot(plane, p) > 0.) ? -kFltMax : (saturate((1. - length(p) / r) * (r / dPdXY)));
}

float SDFTorus(vec2 p, vec2 o, float r1, float r2, float dPdXY)
{
    return saturate((1. - abs((length(p - o) - r1)) / r2) * (r2 / dPdXY));
}

float SDFEllipse(vec2 p, vec2 o, float rx, float ry, float thickness, float dPdXY)
{
    p = p * vec2(max(1., ry/rx), max(1., rx/ry));
    return saturate((1. - abs((length(p - o) - max(rx, ry))) / thickness) * (thickness / dPdXY));
}

float SDFSquorus(vec2 p, vec2 o, vec2 b, float r1, float r2, float dPdXY)
{
    p -= o;
    p.x = sign(p.x) * max(0., abs(p.x) - b.x * 0.5); 
    p.y = sign(p.y) * max(0., abs(p.y) - b.y * 0.5); 

    return saturate((1. - abs((length(p) - r1)) / r2) * (r2 / dPdXY));
}

float SDFHemitorus(vec2 p, vec2 o, float r1, float r2, vec2 plane, float dPdXY)
{
    p -= o;
    return (dot(plane, p) > 0.) ? -kFltMax : (saturate((1. - abs((length(p) - r1)) / r2) * (r2 / dPdXY)));
}

float SDFChord(vec2 p, vec2 o, float r1, float r2,  vec2 planeA, vec2 planeB, float dPdXY)
{
    p -= o;
    return (dot(planeA, p) > 0. && dot(planeB, p) > 0.) ? -kFltMax : (saturate((1. - abs((length(p) - r1)) / r2) * (r2 / dPdXY)));
}

float SDFPolygon(vec2 p, vec2 o, float r1, float r2, float phase, int numFaces, float dPdXY)
{
    p -= o;
    float pTheta = kTwoPi * (0.5 + floor(float(numFaces) * (atan(p.y, p.x) + kPi - phase) / kTwoPi)) / float(numFaces) - kPi + phase;  

    vec2 x = vec2(cos(pTheta), sin(pTheta)) * r1;   
    float perp = length(x * (1.  - dot(p, x) / dot(x, x)));    
    return saturate((1. - abs(perp) / r2) * (r2 / (dPdXY)));
}

float SDFKaleidoscope(vec2 p, vec2 o1, vec2 o2, float r1, float r2, float phase, int numFaces, float dPdXY)
{
    p -= o1;
    float phi = atan(o2.y, o2.x);
    float m = length(o2) / r1;
    float pTheta = kTwoPi * (0.5 + floor(float(numFaces) * (atan(p.y, p.x) + kPi - phase) / kTwoPi)) / float(numFaces) - kPi + phase;

    vec2 x = vec2(cos(pTheta), sin(pTheta)) * r1;    
    vec2 d = vec2(cos(pTheta + phi), sin(pTheta + phi));
    float tPerp = (dot(d, p) - dot(d, x)) / dot(d, d);
    float dist = length(x + d * tPerp - p);
    return saturate((1. - abs(dist) / r2) * (r2 / dPdXY));
}

float SDFCircleSegment(vec2 p, vec2 o, float r, vec2 range, float thickness, float dXYdP)
{
    p -= o;
    if(length2(p) > sqr(r + thickness)) { return 0.; }  

    float phi = atan(p.y, p.x) + kPi;    
    if((range.x < range.y && (phi < range.x || phi > range.y)) || 
       (range.x > range.y && (phi > range.x || phi < range.y)))
    {
        phi = (min(abs(range.x - phi), abs(range.x - kTwoPi * sign(range.x - kPi) - phi)) < 
               min(abs(range.y - phi), abs(range.y - kTwoPi * sign(range.y - kPi) - phi))) ? range.x : range.y;                   
    }

    vec2 pPerp = r * vec2(-cos(phi), sin(-phi));     
    return saturate((thickness - length(p - pPerp)) / (1. * dXYdP));
}

bool Contains(vec2 p, vec4 bBox)
{
    return p.x >= bBox.x && p.x < bBox.z && p.y >= bBox.y && p.y < bBox.w;
}

