//                                              PICKER
/////////////////////////////////////////////////////////////////////////////////////////////////////////////

vec3 Cartesian2DToBarycentric(vec2 p)
{    
    return vec3(p, 0.0) * mat3(vec3(0.0, 1.0 / 0.8660254037844387, 0.0),
                               vec3(1.0, 0.5773502691896257, 0.0),
                               vec3(-1.0, 0.5773502691896257, 0.0));    
}

vec2 BarycentricToCartesian2D(vec3 b)
{    
    return b.yz * mat2(0.5, -0.5, 0.8660254037844387, 0.8660254037844387);   
}

void InitialiseColourPicker(int widgetIdx, inout vec4 rgba)
{
    rgba = vec4(0.);
}

vec3 GetPickerColour()
{
    vec2 bary = saturate(texelFetch(iChannel0, ivec2(2, 0), 0)).xy;
    float angle = texelFetch(iChannel0, ivec2(1, 0), 0).x / kTwoPi;
    return mix(kOne * bary.x, Hue(angle), bary.y * (1. - bary.x));
}

void DrawColourPicker(vec2 xyView, inout vec4 rgba)
{
    #define kPickOrigin vec2(0.5, 0.17)
    #define kPickRadius 0.25
    #define kPickWheelThickness 0.03
    #define kPickKnotRadius (kPickWheelThickness * 0.7)
    #define kPickSatLightSize 0.3

    float wheel = SDFTorus(xyView, kPickOrigin, kPickRadius, kPickWheelThickness, kdPdXY);
    rgba = Blend(rgba, vec4(Hue(atan2(xyView.y - kPickOrigin.y, xyView.x - kPickOrigin.x) / kTwoPi), wheel));

    vec4 hueState = texelFetch(iChannel0, ivec2(1, 0), 0);
    vec4 satLightState = texelFetch(iChannel0, ivec2(2, 0), 0);

    vec2 hueKnot = kPickOrigin + vec2(cos(hueState.x), sin(hueState.x)) * kPickRadius;
    rgba = Blend(rgba, vec4(kOne * 0.5, 1. * SDFTorus(xyView, hueKnot, kPickKnotRadius, kPickWheelThickness * 0.15, kdPdXY)));

    vec3 bary = Cartesian2DToBarycentric((xyView - kPickOrigin) / kPickSatLightSize + vec2(0., 0.5));
    if(bary.x > 0. && bary.y > 0. && bary.x < 1. && bary.y < 1. && bary.z > 0. && bary.z < 1.) 
    { 
        rgba = vec4(mix(kOne * bary.y, Hue(hueState.x / kTwoPi), bary.x * (1. - bary.y)), 1.0);
    }    

    vec2 satLightKnot = BarycentricToCartesian2D(vec3(0., satLightState.x, satLightState.y));    
    satLightKnot = (satLightKnot - vec2(0., 0.5)) * kPickSatLightSize + kPickOrigin;
    rgba.xyz = mix(rgba.xyz, kOne * 0.5, 1. * SDFTorus(xyView, satLightKnot, kPickKnotRadius, kPickWheelThickness * 0.15, kdPdXY));

    rgba = Blend(rgba, vec4(kOne * 0.3, SDFTorus(xyView, kPickOrigin, kPickRadius * 1.15, kPickWheelThickness * 0.1, kdPdXY)));

}

void UpdateColourPicker(vec2 xyView, int stateIdx, vec4 mouse, inout vec4 state)
{
    if(PeekConfig(iFrame))
    {
        float delta = smoothstep(0., 1., GetPeekLeadIn(iFrame));
        switch(stateIdx)
        {
        case 1: state = vec4(kTwoPi * 0.9 * delta); break;
        case 2: state = vec4(delta, 0., 0., 0.); break;
        }
    }

    vec2 mouseView = ScreenToView(mouse.xy, iRes);
    if(stateIdx == 1 && texelFetch(iChannel0, ivec2(2, 0), 0).w == kStateFree)
    {
        float l2 = length2(mouseView - kPickOrigin);
        if(l2 > sqr(kPickRadius - kPickWheelThickness * 1.5) && l2 < sqr(kPickRadius + kPickWheelThickness * 1.5))
        {
            state.x = atan2(mouseView.y - kPickOrigin.y, mouseView.x - kPickOrigin.x);
            state.w = kStateDragging;
        }
    }
    else if(stateIdx == 2)
    {        
        float l2 = length2(mouseView - kPickOrigin);
        if(l2 < sqr(kPickRadius - kPickWheelThickness * 1.5) && texelFetch(iChannel0, ivec2(1, 0), 0).w == kStateFree)
        {

            vec2 satLightKnot = BarycentricToCartesian2D(vec3(0., state.x, state.y));    
            satLightKnot = (satLightKnot - vec2(0., 0.5)) * kPickSatLightSize + kPickOrigin;

            vec3 bary = Cartesian2DToBarycentric((mouseView - kPickOrigin) * 3. + vec2(0., 0.5));            
            state.xy = max(vec2(0.), bary.yz); 
            if(state.x + state.y > 1.) { state.xy /= state.x + state.y; }
            state.w = kStateDragging;
        }
    }

    state.w = kStateFree;
}

