bool InDialBound(vec2 p)
{
    return p.x >= -kDialRadius * 1.01 && p.x < kDialRadius * 1.01 && p.y >= -kDialRadius * 1.01 && p.y < kDialRadius * 1.01;
}

void DrawBrightnessIcon(vec2 xyView, inout vec4 rgba)
{
    if(InDialBound(xyView))
    {
        float brightness = mix(0.25, 0.4, LoadDialParam(kIDBrightness, iChannel0));
        rgba = Blend(rgba, vec4(kOne * 0.7, SDFCircle(xyView, vec2(0., 0.), kDialRadius * 0.15, kdPdXY)));    
        for(int i = 0; i < 8; ++i)
        {
            vec2 v = vec2(cos(kTwoPi * float(i) / 8.), sin(kTwoPi * float(i) / 8.));
            rgba = Blend(rgba, vec4(kOne * 0.7, SDFLine(xyView, 0.25 * kDialRadius * v, brightness * kDialRadius * v, 0.8 * kDialThickness * kdPdXY, kdPdXY)));
        }
    }
}

void DrawThicknessIcon(vec2 xyView, inout vec4 rgba)
{
    if(InDialBound(xyView))
    {
        rgba = Blend(rgba, vec4(kOne * 0.7, SDFCircle(xyView, 0.5 * kDialRadius * vec2(-0.6, 0.), kDialRadius * 0.05, kdPdXY)));    
        rgba = Blend(rgba, vec4(kOne * 0.7, SDFCircle(xyView, 0.5 * kDialRadius * vec2(-0.1, 0.), kDialRadius * 0.1, kdPdXY)));    
        rgba = Blend(rgba, vec4(kOne * 0.7, SDFCircle(xyView, 0.5 * kDialRadius * vec2(0.5, 0.), kDialRadius * 0.15, kdPdXY)));    
    }
}

void DrawFOVIcon(vec2 xyView, inout vec4 rgba)
{
    if(InDialBound(xyView))
    {
        float alpha = mix(0.2, 1., LoadDialParam(kIDAlpha, iChannel0));
        rgba = Blend(rgba, vec4(kOne * 0.7, alpha * SDFLine(xyView, 0.3 * kDialRadius * vec2(-0.7, -0.8), 0.3 * kDialRadius * vec2(0., 0.8), kIconThickness * kdPdXY, kdPdXY)));
        rgba = Blend(rgba, vec4(kOne * 0.7, alpha * SDFLine(xyView, 0.3 * kDialRadius * vec2(0.7, -0.8), 0.3 * kDialRadius * vec2(0., 0.8), kIconThickness * kdPdXY, kdPdXY)));
        rgba = Blend(rgba, vec4(kOne * 0.7, alpha * SDFLine(xyView, 0.3 * kDialRadius * vec2(-0.3, -0.2), 0.3 * kDialRadius * vec2(0.3, -0.2), kIconThickness * kdPdXY, kdPdXY)));
    }
}

void DrawHardnessIcon(vec2 xyView, inout vec4 rgba)
{
    if(InDialBound(xyView))
    {
        float hardness = LoadDialParam(kIDHardness, iChannel0);
        rgba = Blend(rgba, vec4(kOne * 0.7, SDFCircle(xyView,vec2(-0.), kDialRadius * mix(0.5, 0.3, hardness), mix(20., 1., hardness) * kdPdXY))); 
    }
}

void DrawBrushIcon(vec2 xyView, inout vec4 rgba)
{
    if(InDialBound(xyView))
    {        
       rgba = Blend(rgba, vec4(kOne * 0.7, SDFTorus(xyView, vec2(0.), kDialRadius * mix(0.1, 0.4, LoadDialParam(kIDThickness, iChannel0)), kDialRadius * 0.05, 1. * kdPdXY)));
    }
}

const float[kNumDials] kDialInits = float[kNumDials](0.4, 0.0, 0.8, 0.6);
const int[kNumDials] kDialSnap = int[kNumDials](0, 0, 0, 0);

void InitialiseDialWidget(int widgetIdx, inout vec4 rgba)
{
    #define kDialsPerRow 4 
    #define kDialPadding 0.4
    #define kDialYOrigin -0.21

    widgetIdx -= kDialStartID;
    int rowIdx = widgetIdx / kDialsPerRow;
    int colIdx = widgetIdx % kDialsPerRow;
    int dialsInRow = kDialsPerRow;//min(kDialsPerRow, kNumDials - (rowIdx * kDialsPerRow)) - 1;
    float rowLength = float(dialsInRow) * 2. * kDialRadius * (1. + kDialPadding);
    float y = kDialYOrigin + mix(0., 0.15, float(rowIdx));
    float x = 0.6 + rowLength * 0.5 * mix(-1., 1., float(colIdx) / float(dialsInRow));    

    rgba.xy = vec2(x,y);
    rgba.z = clamp(kDialInits[widgetIdx], 1e-2, 1.) * kTwoPi * 0.9;
    rgba.w = kStateFree;
} 

void DrawDialWidget(vec2 xyView, vec2 dialPos, float dialRadius, float theta, int snap, inout vec4 rgba)
{    
    vec3 colour = saturate(mix(vec3(0., 1., 0.), vec3(1., 0., 0.), theta / (kTwoPi * 0.9)) * 2.);
    //vec3 colour = mix(vec3(0., 0.4, 1.), vec3(1., 0., 0.), theta / (kTwoPi * 0.9));
    vec2 v = vec2(cos(theta - kPi), sin(theta - kPi));    

    // Draw the background
    vec4 inter = vec4(kOne * 0.3, SDFCircleSegment(xyView, dialPos, dialRadius, vec2(0., kTwoPi * 0.9), 2. * kDialThickness * kdPdXY, kdPdXY));
    inter = Blend(inter, vec4(kOne * 0.3, SDFLine(xyView, dialPos + v * dialRadius * 0.7, dialPos + v * dialRadius, 2. * kDialThickness * kdPdXY, kdPdXY)));

    if(snap > 0)
    {
        float phi = (atan(xyView.y - dialPos.y, xyView.x - dialPos.x) + kPi) / (kTwoPi * 0.9);
        float shade = float(int(0.5 + phi * float(snap - 1)) & 1);
        inter.xyz = saturate(inter.xyz * (1. + 2. * shade));
    }

    inter.w *= .5;

    // Draw the foreground
    inter = Blend(inter, vec4(colour, SDFCircleSegment(xyView, dialPos, dialRadius, vec2(0., theta), dialRadius * 0.1, kdPdXY)));
    inter = Blend(inter, vec4(colour, SDFLine(xyView, dialPos + v * dialRadius * 0.7, dialPos + v * dialRadius, dialRadius * 0.1, kdPdXY)));   

    // Blend with main canvas
    rgba = Blend(rgba, inter);
}

void UpdateDialWidget(vec2 xyView, int widgetIdx, vec4 mouse, inout vec4 state)
{
    if(PeekConfig(iFrame))
    {
        float delta = smoothstep(0., 1., GetPeekLeadIn(iFrame));
        state.z = mix(0., clamp(kDialInits[widgetIdx], 1e-2, 1.) * kTwoPi * 0.9, delta);
    }

    vec2 mouseView = ScreenToView(mouse.xy, iRes);
    float l2 = length2(state.xy - mouseView) ;
    if(l2 > sqr(kDialRadius * 0.2) && l2 < sqr(kDialRadius * 1.2))
    {
        state.z = (atan(mouseView.y - state.y, mouseView.x - state.x) + kPi) / (kTwoPi * 0.9);
        int snap = kDialSnap[widgetIdx];
        if(snap > 0)
        {
            state.z = floor(0.5 + state.z * float(snap - 1)) / float(snap - 1);
        }
        if(state.z < 1e-3 || state.z > 1.05) { state.z = 1e-3; }
        else if(state.z > 1.) { state.z = 1.; }
        state.z = saturate(state.z);
        state.z *= kTwoPi * 0.9;
        state.w = kStateDragging;
    }
    else
    {
        state.w = kStateFree;
    }    
}


void DrawDials(vec2 xyView, inout vec4 rgba)
{
    vec4 states[kNumDials];
    int dialIdx;
    for(dialIdx = 0; dialIdx < kNumDials; ++dialIdx)
    {
        states[dialIdx] = LoadState(kDialStartID + dialIdx, iChannel0);
        if(length2(xyView - states[dialIdx].xy) < sqr(kDialRadius * 1.2)) { break; }
    }

    if(dialIdx != kNumDials)
    {
        DrawDialWidget(xyView, states[dialIdx].xy, kDialRadius, states[dialIdx].z, kDialSnap[dialIdx], rgba);
    }

    // Draw the icons for each dial
    DrawBrushIcon(xyView - states[0].xy, rgba);
    DrawHardnessIcon(xyView - states[1].xy, rgba);
    DrawBrightnessIcon(xyView - states[2].xy, rgba);
    DrawFOVIcon(xyView - states[3].xy, rgba);
}

