#define kTogglesPerRow 4 
#define kTogglePadding 0.4
#define kToggleYOrigin -0.35
#define kToggleBoundThickness 0.15
#define kToggleDims vec2(0.04, 0.09)

const int[kNumToggles] kToggleInits = int[kNumToggles](1, 1, 1, 1, 1);

bool InToggleBound(vec2 p)
{
    return p.x >= -kToggleDims.x * 0.6 && p.x < kToggleDims.x * 0.6 && p.y >= -kToggleDims.y * 0.6 && p.y < kToggleDims.y * 0.6;
}

void DrawNormaliseIcon(vec2 xyView, inout vec4 rgba)
{
    if(InToggleBound(xyView))
    {        
        xyView += sin(1. * kTwoPi * xyView.x / kToggleDims.x) * kToggleDims.x * 0.2;
        rgba = Blend(rgba, vec4(kOne * 0.7, SDFLine(xyView, vec2(-kToggleDims.x * 0.5, 0.), vec2(kToggleDims.x * 0.5, 0.), kToggleBoundThickness * 0.015, kdPdXY)));         
    }
}

void DrawGradeIcon(vec2 xyView, inout vec4 rgba)
{
    if(InToggleBound(xyView))
    {        
       for(int i = 0; i < 3; ++i)
       {
           float theta = kTwoPi * float(i) / 3.;
           vec2 o = vec2(cos(theta), sin(theta)) * kToggleDims.x * 0.15;
           rgba = Blend(rgba, vec4(kOne * 0.7, SDFTorus(xyView, o, kToggleDims.x * 0.25, kToggleBoundThickness * 0.013, kdPdXY)));     
       }    
    }
}

void DrawBloomIcon(vec2 xyView, inout vec4 rgba)
{
    if(InToggleBound(xyView))
    {        
        #define kToggleBloomRadius (kToggleDims.x * 0.35)
        for(int i = 0; i < 4; ++i)
        {
            if(cwiseMax(abs(xyView)) < kToggleDims.x * 0.45)
            {
                vec2 xyArc = vec2(sign(float(((i>>1)<<1)-1)),sign(float(((i&1)<<1)-1))) * kToggleDims.x * 0.37;
                float chord = SDFTorus(xyView, xyArc, kToggleBloomRadius, kToggleDims.x * kToggleBoundThickness * 0.3, kdPdXY);      
                rgba = Blend(rgba, vec4(kOne * 0.7, chord));       
            }
        }
    }
}

void DrawAberrationIcon(vec2 xyView, inout vec4 rgba)
{
    if(InToggleBound(xyView))
    {        
       for(int i = 0; i < 3; ++i)
       {
           float radius = mix(0.45, 0.2, float(i) / 2.) * kToggleDims.x;
           float arc = SDFHemitorus(xyView, vec2(0., radius * 0.1 - kToggleDims.x * 0.2), radius, kToggleDims.x * 0.05, vec2(0., -1.), 1. * kdPdXY);       
           if(arc > 0.) rgba = Blend(rgba, vec4(kOne * 0.7, arc));
       }
    }
}

void DrawSpotlightIcon(vec2 xyView, inout vec4 rgba)
{
    if(InToggleBound(xyView))
    {        
        rgba = Blend(rgba, vec4(kOne * 0.7, SDFEllipse(xyView, vec2(0., kToggleDims.y * -0.2), 
                                                       kToggleDims.x * 0.3, kToggleDims.x * 0.2, 
                                                       kToggleBoundThickness * 0.013, kdPdXY)));

        for(int i = 0; i < 2; ++i)
        {
            rgba = Blend(rgba, vec4(kOne * 0.7, SDFLine(xyView, vec2(0., kToggleDims.y * 0.2), 
                                                                vec2((float(i) * 2. - 1.) * kToggleDims.x * 0.3, kToggleDims.y * -0.1), 
                                                                kToggleBoundThickness * 0.013, kdPdXY)));
        }
    }
}

void InitialiseToggleWidget(int widgetIdx, inout vec4 rgba)
{    
    widgetIdx -= kToggleStartID;
    float x = 0.31 + 0.1 * mix(-1., 1., float(widgetIdx) / 2.);

    rgba.xy = vec2(x,kToggleYOrigin);
    rgba.zw = vec2(kToggleInits[widgetIdx]);
} 

void DrawToggleWidget(vec2 xyView, vec2 togglePos, vec2 dims, float state, inout vec4 rgba)
{
    float radius = min(dims.x, dims.y) * 0.5;

    // Draw the bounding capsule
    rgba = Blend(rgba, vec4(kOne * 0.3, SDFSquorus(xyView, togglePos, vec2(0., dims.y - radius * 2.), radius, radius * kToggleBoundThickness, kdPdXY)));

    // Draw the switch
    vec3 colour = mix(vec3(0.5), kOne, state);
    rgba = Blend(rgba, vec4(colour, SDFCircle(xyView, togglePos + vec2(0., (dims.y * 0.5 - radius) * mix(-1., 1., state)), radius * 0.6, kdPdXY)));

}

bool InIconBound(vec2 p)
{
    return p.x >= -kToggleDims.x * 0.6 && p.x < kToggleDims.x * 0.6 && p.y >= -kToggleDims.y * 1.5 && p.y < -kToggleDims.y * .5;
}

void DrawToggles(vec2 xyView, inout vec4 rgba)
{
    vec4 states[kNumToggles];
    int foundToggleIdx = -1, foundIconIdx = -1;
    for(int toggleIdx = 0; toggleIdx < kNumToggles; ++toggleIdx)
    {
        states[toggleIdx] = LoadState(kToggleStartID + toggleIdx, iChannel0);

        if(InToggleBound(xyView - states[toggleIdx].xy)) { foundToggleIdx = toggleIdx; break; }

        if(InIconBound(xyView - states[toggleIdx].xy)) { foundIconIdx = toggleIdx; break; }
    }

    if(foundToggleIdx != kNumToggles)
    {
        DrawToggleWidget(xyView, states[foundToggleIdx].xy, kToggleDims, states[foundToggleIdx].w, rgba);
    }

    switch(foundIconIdx)
    {
        case 0: DrawNormaliseIcon(xyView - states[0].xy + vec2(0., kToggleDims.y * 1.), rgba); break;
        case 1: DrawGradeIcon(xyView - states[1].xy + vec2(0., kToggleDims.y * 1.), rgba); break;
        case 2: DrawBloomIcon(xyView - states[2].xy + vec2(0., kToggleDims.y * 1.), rgba); break;
        case 3: DrawAberrationIcon(xyView - states[3].xy + vec2(0., kToggleDims.y * 1.), rgba); break;
        case 4: DrawSpotlightIcon(xyView - states[4].xy + vec2(0., kToggleDims.y * 1.), rgba); break;
    }
}

void UpdateToggleWidget(vec2 xyView, vec4 mouse, inout vec4 state)
{    
    vec2 xyTog = ScreenToView(mouse.xy, iRes) - state.xy;
    if(InToggleBound(xyTog))
    {
       state.z = float(xyTog.y > 0.);
    }   

   if(state.z > 0. && state.w < 1.) { state.w = min(1., state.w + 0.1); }
   else if(state.z == 0. && state.w > 0.) { state.w = max(0., state.w - 0.1); }
}

