#define kButtonDims vec2(0.09, 0.09)

bool InButtonBound(vec2 p)
{
    return p.x >= -kButtonDims.x * 0.6 && p.x < kButtonDims.x * 0.6 && p.y >= -kButtonDims.y * 0.6 && p.y < kButtonDims.y * 0.6;
}

void DrawResetIcon(vec2 xyView, inout vec4 rgba)
{
    if(InButtonBound(xyView))
