    state.z = (InButtonBound(xyTog)) ? iMouse.z : 0.;

    if(state.z > 0. && state.w < 1.) { state.w = 1.; }
    else { state.w = max(0., state.w - 0.01); }
}

vec2 ScreenToHemiSpace(vec2 xyScreen, vec2 res)
{
    return xyScreen / res.y;
}

vec4 InitialiseDrawingArea(vec2 xyHemi)
{
    vec4 rgba = vec4(kZero, 1.);
    for(int i = 0; i < 5; ++i)
    {
        float delta = (float(i) + 0.5) / 5.;
        vec3 colour = mix(kOne, Hue(mix(0.45, 1.18, delta)), 0.7);
        float phi = kTwoPi * delta;
        vec2 o = vec2(0.5) + vec2(cos(phi), sin(phi)) * 0.3;

        float d = exp(-length2(xyHemi - o) / sqr(0.2));

        if(d > 1e-3)
        {
            rgba = Blend(rgba, vec4(5. * colour, d));
        }

        rgba = Blend(rgba, vec4(100. * colour, SDFTorus(xyHemi, o, 0.1, 0.01, 3. * kdPdXY)));
    }
    return rgba;
}

void mainImage( out vec4 rgba, in vec2 xyScreen )
{
    rgba = vec4(0.);    

    vec2 xyView = ScreenToView(xyScreen, iRes);   
    vec4 mouse = iMouse;
    bool peekConfig = PeekConfig(iFrame);
    bool isQDown = peekConfig || IsKeyDown(iChannel1, KEY_Q);
    bool isADown = IsKeyDown(iChannel1, KEY_A);
    bool showConfig = isQDown || isADown || peekConfig;        
    rgba = texelFetch(iChannel0, ivec2(xyScreen), 0);

    #define kBackgroundAlpha 1.

    if(isADown)
    {
        mouse.xy /= kPiPSize;
    }

    // Handle the UI state
    if(int(xyScreen.y) == 0 && int(xyScreen.x) <= kUIState)
    {         
        int widgetIdx = int(xyScreen.x);

        // Persistent mouse state
        if(widgetIdx == 0)
        {
            rgba = mouse;
            rgba.xy = ScreenToHemiSpace(rgba.xy, iResolution.xy);   
            rgba.w = rgba.w + 1.;
            return;
        }    
        // Config window state
        else if(widgetIdx == 3)
        {
            rgba.x = saturate(rgba.x + 3. * iTimeDelta * (float(isQDown) * 2. - 1.));
            rgba.y = saturate(rgba.y + 3. * iTimeDelta * (float(isADown) * 2. - 1.));
            rgba.z = float(isQDown || isADown);
            return;
        }

        // Only update these when the config window is visible so we don't mess with the controls when it's hidden
        if(showConfig || iFrame == 0)
        {
            if(widgetIdx >= 1 && widgetIdx <= 2)
            {
                if(iFrame == 0) { InitialiseColourPicker(widgetIdx, rgba); }

                UpdateColourPicker(xyView, widgetIdx, mouse, rgba);
            }
            else if(widgetIdx < kDialStartID + kNumDials)
            {
                if(iFrame == 0) { InitialiseDialWidget(widgetIdx, rgba); }

                UpdateDialWidget(xyView, widgetIdx - kDialStartID, mouse, rgba); 
                if(mouse.z <= 0.) { rgba.w = kStateFree; }
            }  
            else if(widgetIdx < kToggleStartID + kNumToggles)
            {
                if(iFrame == 0) { InitialiseToggleWidget(widgetIdx, rgba); }

                UpdateToggleWidget(xyView, mouse, rgba);
            } 
            else if(widgetIdx < kButtonStartID + kNumButtons)
            {
                if(iFrame == 0) { InitialiseButtonWidget(widgetIdx, rgba);  }

                UpdateButtonWidget(xyView, mouse, rgba);
            }
        }

        return;
    }

    // If the configuration pane is visible
    if(showConfig || iFrame == 0)
    {           
        vec2 xyHemi = ScreenToHemiSpace(xyScreen, iResolution.xy);                  
        bool isDrawingArea = (length2(xyHemi - vec2(0.5)) < sqr(0.49));

        if(isDrawingArea)
        {             
             if(PeekConfig(iFrame)) 
             { 
                 rgba = InitialiseDrawingArea(xyHemi); 
             }
             else if(IsButtonDown(kIDReset, iChannel0)) { rgba = vec4(kZero, 1.0); }        

        }

        // Hashed backgroundq
        if(xyHemi.x < 1.05 && !isDrawingArea) 
        {
            rgba = vec4(kZero, kBackgroundAlpha);
            rgba = saturate(rgba + vec4(0.2 * saturate(sin01(.75 * (xyScreen.x + xyScreen.y)) * 5. - 4.)));
        }

        vec4 state = texelFetch(iChannel0, ivec2(0), 0);
        if(xyHemi.x < 1.) 
        {   
            // Handle painting ops
            vec2 m1 = ScreenToHemiSpace(mouse.xy, iResolution.xy); 
            vec2 m0 = (mouse.w > 0.) ? m1 : state.xy;

            if(length2(m1 - vec2(0.5)) < sqr(0.5))
            {
                if(mouse.z > 0. && isDrawingArea)
                {               
                    float thickness = mix(0.001, 0.5, sqr(LoadDialParam(kIDThickness, iChannel0)));
                    float hardness = mix(thickness, 1. / iResolution.y, LoadDialParam(kIDHardness, iChannel0));
                    float brightness = pow(2., mix(-2., 8., LoadDialParam(kIDBrightness, iChannel0)));// / sqr(10. * thickness);
                    float line = SDFLine(xyHemi, m0, m1, thickness, hardness);
                    float alpha = sqr(LoadDialParam(kIDAlpha, iChannel0));
                    vec3 colour = GetPickerColour();

                    rgba.xyz = mix(rgba.xyz, colour * brightness, line * alpha);
                    //rgba.xyz = max(rgba.xyz, rgba.xyz + 0.1 * mix(kOne, Hue(state.w / 100.), 0.5) * line);
                }           
            }    
         }
         else
         {
             // Render the widgets
             rgba = vec4(kZero, kBackgroundAlpha);
             DrawDials(xyView, rgba);
             DrawToggles(xyView, rgba);
             DrawButtons(xyView, rgba);
             DrawColourPicker(xyView, rgba);
         }               
    }
 }
